            a = random.randint(1, n)
            b = random.randint(1, n)
            while b == a:
                b = random.randint(1, n)
            pairs.append([a, b])
        got = sol.maxSubarrays(n, pairs)
        exp = brute(n, pairs)
        if got != exp:
