def all_alternating(n: int) -> List[List[int]]:
    """All alternating permutations of 1..n, sorted lexicographically."""
    out = []
    for p in permutations(range(1, n + 1)):
        if all((p[i] - p[i + 1]) & 1 for i in range(n - 1)):
            out.append(list(p))
    out.sort()
    return out


def brute(n: int, k: int, table=None) -> List[int]:
    if table is None:
        table = all_alternating(n)
    return table[k - 1] if 1 <= k <= len(table) else []


def run_tests() -> bool:
    sol = Solution()
    mismatches = []

    # --- Provided examples -------------------------------------------------
    examples = [
        (4, 6, [3, 4, 1, 2]),
        (3, 2, [3, 2, 1]),
        (2, 3, []),
    ]
    for (n, k, exp) in examples:
        got = sol.permute(n, k)
        if got != exp:
            mismatches.append((n, k, exp, got))

    # --- Exhaustive brute-force comparison ---------------------------------
    for n in range(1, 9):
        table = all_alternating(n)
        total = len(table)
        for k in range(1, total + 3):   # include out-of-range k = total+1, total+2
            exp = brute(n, k, table)
            got = sol.permute(n, k)
            if got != exp:
                mismatches.append((n, k, exp, got))

    if mismatches:
        print("FAIL: %d mismatch(es) found" % len(mismatches))
        for (n, k, exp, got) in mismatches:
            print(f"  n={n}, k={k}, expected={exp}, got={got}")
        return False

    print("PASS: all provided examples and exhaustive n=1..8 checks matched.")
    return True


if __name__ == "__main__":
    run_tests()

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0])
    M = int(data[1])

    # L[x] = max black y in row x, default 0
    # R[x] = min white y - 1 in row x, default N
    L = {}
    R = {}
    idx = 2
    for _ in range(M):
        x = int(data[idx])
        y = int(data[idx + 1])
        c = data[idx + 2]
        idx += 3
        if c == b'B':
            if x in L:
                if y > L[x]:
                    L[x] = y
            else:
                L[x] = y
        else:
            r = y - 1
            if x in R:
                if r < R[x]:
                    R[x] = r
            else:
                R[x] = r

    rows = set(L) | set(R)

    # same-row consistency
    for x in rows:
        lx = L.get(x, 0)
        rx = R.get(x, N)
        if lx > rx:
            sys.stdout.write("No\n")
            return

    # global monotonicity check
    sorted_rows = sorted(rows)
    min_r = N
    for x in sorted_rows:
        lx = L.get(x, 0)
        rx = R.get(x, N)
        if rx < min_r:
            min_r = rx
        if lx > min_r:
            sys.stdout.write("No\n")
            return

    sys.stdout.write("Yes\n")

if __name__ == "__main__":
    solve()

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        # p = A * B * C  (exactly two stars)
        i1 = p.index('*')
        i2 = p.index('*', i1 + 1)
        A = p[:i1]
        B = p[i1 + 1:i2]
        C = p[i2 + 1:]
        n = len(s)
        INF = float('inf')

        def find_all(text, pat):
            """All (possibly overlapping) start indices of pat in text, via KMP: O(len(text)+len(pat))."""
            m = len(pat)
            if m == 0:
                return []
            pi = [0] * m
            j = 0
            for i in range(1, m):
                c = pat[i]
                while j and c != pat[j]:
                    j = pi[j - 1]
                if c == pat[j]:
                    j += 1
                pi[i] = j
            res = []
            j = 0
            for i, c in enumerate(text):
                while j and c != pat[j]:
                    j = pi[j - 1]
                if c == pat[j]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = pi[j - 1]
            return res

        lenA, lenB, lenC = len(A), len(B), len(C)

        # ---- B empty: pattern is A*C (or a single literal / empty) ----
        if lenB == 0:
            if lenA == 0 and lenC == 0:
                return 0                      # "**"
            if lenA == 0:                     # *C
                return lenC if s.find(C) != -1 else -1
            if lenC == 0:                     # A*
                return lenA if s.find(A) != -1 else -1
            occA = find_all(s, A)
            occC = find_all(s, C)
            if not occA or not occC:
                return -1
            latestA = [-1] * (n + 1)          # latestA[x] = max A-start with A-end <= x
            for a0 in occA:
                a1 = a0 + lenA
                if a0 > latestA[a1]:
                    latestA[a1] = a0
            for x in range(1, n + 1):
                if latestA[x - 1] > latestA[x]:
                    latestA[x] = latestA[x - 1]
            best = INF
            for c0 in occC:
                a0 = latestA[c0]
                if a0 != -1:
                    span = c0 + lenC - a0
                    if span < best:
                        best = span
            return best if best < INF else -1

        # ---- B non-empty: anchor on each occurrence of B ----
        occB = find_all(s, B)
        if not occB:
            return -1

        latestA = None
        if lenA > 0:
            occA = find_all(s, A)
            latestA = [-1] * (n + 1)
            for a0 in occA:
                a1 = a0 + lenA
                if a0 > latestA[a1]:
                    latestA[a1] = a0
            for x in range(1, n + 1):
                if latestA[x - 1] > latestA[x]:
                    latestA[x] = latestA[x - 1]

        nextC = None
        if lenC > 0:
            occC = find_all(s, C)
            nextC = [INF] * (n + 1)           # nextC[x] = min C-start >= x
            for c0 in occC:
                if c0 < nextC[c0]:
                    nextC[c0] = c0
            for x in range(n - 1, -1, -1):
                if nextC[x + 1] < nextC[x]:
                    nextC[x] = nextC[x + 1]

        best = INF
        for b0 in occB:
            b1 = b0 + lenB
            if lenA == 0:
                start = b0                    # A is empty -> substring begins at B
            else:
                start = latestA[b0]           # rightmost A that ends at/before b0
                if start == -1:
                    continue
            if lenC == 0:
                end = b1                      # C is empty -> substring ends at B
            else:
                c0 = nextC[b1]                # earliest C that starts at/after b1
                if c0 == INF:
                    continue
                end = c0 + lenC
            span = end - start
            if span < best:
                best = span
        return best if best < INF else -1

