class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # prefix function of str2
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and str2[i] != str2[j]:
                j = pi[j - 1]
            if str2[i] == str2[j]:
                j += 1
            pi[i] = j

        # KMP automaton: states 0..m (length of longest prefix of str2
        # that is a suffix of the text read so far)
        nxt = [[0] * 26 for _ in range(m + 1)]
        for s in range(m):
            row = nxt[s]
            for ci in range(26):
                c = chr(97 + ci)
                j = s
                while j > 0 and str2[j] != c:
                    j = pi[j - 1]
                if str2[j] == c:
                    j += 1
                row[ci] = j
        # from state m, the relevant border is the longest proper border
        b = pi[m - 1] if m > 0 else 0
        for ci in range(26):
            nxt[m][ci] = nxt[b][ci]

        # reachability masks (bitmask over states) for all chars / non-m chars
        full = [0] * (m + 1)
        nonm = [0] * (m + 1)
        for s in range(m + 1):
            fm = 0
            nm = 0
            for ci in range(26):
                t = nxt[s][ci]
                fm |= (1 << t)
                if t != m:
                    nm |= (1 << t)
            full[s] = fm
            nonm[s] = nm

        # backward DP: dp[p] = bitmask of states from which positions p..L-1
        # can be completed satisfying all constraints
        dp = [0] * (L + 1)
        dp[L] = (1 << (m + 1)) - 1
        mstart = m - 1
        for p in range(L - 1, -1, -1):
            typ = str1[p - mstart] if p >= mstart else None
            nxtdp = dp[p + 1]
            if typ == 'T':
                if (nxtdp >> m) & 1:
                    cur = 0
                    for s in range(m + 1):
                        if (full[s] >> m) & 1:
                            cur |= (1 << s)
                    dp[p] = cur
                else:
                    dp[p] = 0
            elif typ == 'F':
                cur = 0
                for s in range(m + 1):
                    if nonm[s] & nxtdp:
                        cur |= (1 << s)
                dp[p] = cur
            else:
                cur = 0
                for s in range(m + 1):
                    if full[s] & nxtdp:
                        cur |= (1 << s)
                dp[p] = cur

        if not (dp[0] & 1):
            return ""

        # greedy lexicographically smallest reconstruction
        res = []
        s = 0
        for p in range(L):
            typ = str1[p - mstart] if p >= mstart else None
            nxtdp = dp[p + 1]
            for ci in range(26):
                t = nxt[s][ci]
                if typ == 'T' and t != m:
                    continue
                if typ == 'F' and t == m:
                    continue
                if (nxtdp >> t) & 1:
                    res.append(chr(97 + ci))
                    s = t
                    break
        return ''.join(res)

from functools import lru_cache


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        # free(rem, started, s, p) = number of ways to fill `rem` free
        # decimal digits (0-9) so that, starting from prefix state
        # (started, s = digit sum, p = digit product), the final number is
        # beautiful.  Independent of n, so it is shared by both count calls.
        @lru_cache(maxsize=None)
        def free(rem: int, started: bool, s: int, p: int) -> int:
            if rem == 0:
                return 1 if (started and s > 0 and p % s == 0) else 0
            total = 0
            if started:
                for d in range(10):
                    total += free(rem - 1, True, s + d, p * d)
            else:
                # leading zero: still unstarted (counts shorter numbers)
                total += free(rem - 1, False, 0, 1)
                for d in range(1, 10):
                    total += free(rem - 1, True, d, d)
            return total

        def count(n: int) -> int:
            # number of beautiful integers in [1, n]
            if n <= 0:
                return 0
            digits = list(map(int, str(n)))
            L = len(digits)
            res = 0
            started = False
            s = 0
            p = 1
            for i in range(L):
                di = digits[i]
                # branch off with a strictly smaller digit; the rest is free
                for d in range(di):
                    if not started:
                        if d == 0:
                            res += free(L - 1 - i, False, 0, 1)
                        else:
                            res += free(L - 1 - i, True, d, d)
                    else:
                        res += free(L - 1 - i, True, s + d, p * d)
                # stay tight with the actual digit
                if not started:
                    if di != 0:
                        started = True
                        s = di
                        p = di
                else:
                    s += di
                    p *= di
            if started and s > 0 and p % s == 0:
                res += 1
            return res

        return count(r) - count(l - 1)

import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    P = int(data[1])
    half = N // 2
    Kmax = N * (N - 1) // 2

    # factorials up to N
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i-1] * i % P
    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], P - 2, P)
    for i in range(N, 0, -1):
        invfact[i-1] = invfact[i] * i % P

    # binomial coefficients up to N
    C = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        C[i][0] = C[i][i] = 1
        for j in range(1, i):
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % P

    # transition list for (previous layer size a, new layer size b)
    # factor: (z^a - 1)^b * z^{C(b,2)} * (1/b!)  where z = 1+x
    trans = [[None] * (half + 1) for _ in range(half + 1)]
    for a in range(1, half + 1):
        for b in range(1, half + 1):
            lst = []
            invfb = invfact[b]
            cb2 = b * (b - 1) // 2
            for j in range(b + 1):
                delta = a * j + cb2
                coef = C[b][j] * invfb % P
                if (b - j) & 1:
                    coef = (-coef) % P
                if coef:
                    lst.append((delta, coef))
            trans[a][b] = lst

    # max polynomial length for a given number of used vertices
    lims = [0] * (N + 1)
    for used in range(N + 1):
        lims[used] = used * (used - 1) // 2 + 1

    # DP over layers
    # state: (even_used, odd_used, last_layer_size) -> polynomial in z
    cur = {(1, 0, 1): [1]}
    parity = 0  # 0 even, 1 odd
    final = [0] * (Kmax + 1)

    while cur:
        nxt = {}
        next_parity = 1 - parity
        for (e, o, last), src in cur.items():
            nz = [(k, v) for k, v in enumerate(src) if v]
            if not nz:
                continue
            if parity == 0:
                maxb = half - o
                if maxb <= 0:
                    continue
                for b in range(1, maxb + 1):
                    new_e = e
                    new_o = o + b
                    used_new = new_e + new_o
                    lst = trans[last][b]
                    if new_e == half and new_o == half:
                        dest = final
                    else:
                        key = (new_e, new_o, b)
                        dest = nxt.get(key)
                        if dest is None:
                            dest = [0] * lims[used_new]
                            nxt[key] = dest
                    for k, v in nz:
                        for delta, coef in lst:
                            dest[k + delta] += v * coef
            else:
                maxb = half - e
                if maxb <= 0:
                    continue
                for b in range(1, maxb + 1):
                    new_e = e + b
                    new_o = o
                    used_new = new_e + new_o
                    lst = trans[last][b]
                    if new_e == half and new_o == half:
                        dest = final
                    else:
                        key = (new_e, new_o, b)
                        dest = nxt.get(key)
                        if dest is None:
                            dest = [0] * lims[used_new]
                            nxt[key] = dest
                    for k, v in nz:
                        for delta, coef in lst:
                            dest[k + delta] += v * coef
        for key, arr in nxt.items():
            nxt[key] = [x % P for x in arr]
        cur = nxt
        parity = next_parity

    final = [x % P for x in final]
    mul = fact[N-1]
    for i in range(Kmax + 1):
        final[i] = final[i] * mul % P

    # binomial coefficients up to Kmax
    factK = [1] * (Kmax + 1)
    for i in range(1, Kmax + 1):
        factK[i] = factK[i-1] * i % P
    invfactK = [1] * (Kmax + 1)
    invfactK[Kmax] = pow(factK[Kmax], P - 2, P)
    for i in range(Kmax, 0, -1):
        invfactK[i-1] = invfactK[i] * i % P

    ans = []
    for M in range(N - 1, Kmax + 1):
        s = 0
        for K in range(M, Kmax + 1):
            fk = final[K]
            if fk:
                comb = factK[K] * invfactK[M] % P * invfactK[K - M] % P
                s += fk * comb
        ans.append(str(s % P))
    print(' '.join(ans))

if __name__ == "__main__":
    main()

import sys

def solve():
    data = sys.stdin.read().split()
    n = int(data[0])
    S = data[1]
    T = data[2]

    # 1) Build the required mapping f from each distinct char of S.
    f = {}
    for a, b in zip(S, T):
        if a in f:
            if f[a] != b:
                print(-1)
                return
        else:
            f[a] = b

    # 2) Edges c -> f(c) for c with f(c) != c.  E = number of such edges.
    edges = {}
    E = 0
    for c, d in f.items():
        if c != d:
            edges[c] = d
            E += 1

    # indegree over these edges
    indeg = {}
    for c, d in edges.items():
        indeg[d] = indeg.get(d, 0) + 1

    # 3) Find cycles; a cycle is "pure" iff every node on it has indegree exactly 1.
    color = {}
    P = 0
    for s in edges:
        if color.get(s, 0) != 0:
            continue
        path = []
        node = s
        while node is not None and color.get(node, 0) == 0:
            color[node] = 1
            path.append(node)
            node = edges.get(node)
        if node is not None and color.get(node, 0) == 1:
            idx = path.index(node)
            cyc = path[idx:]
            if all(indeg.get(v, 0) == 1 for v in cyc):
                P += 1
        for v in path:
            color[v] = 2

    # 4) Impossibility: T uses all 26 letters (=> S too, f bijection) and a cycle exists.
    if len(set(T)) == 26 and P > 0:
        print(-1)
    else:
        print(E + P)

solve()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    pos = 0
    N = int(data[pos]); pos += 1
    p = int(data[pos]); pos += 1
    A = []
    for _ in range(N):
        A.append([int(x) for x in data[pos:pos + N]])
        pos += N

    # ---- p == 2 special case -------------------------------------------
    # Entries are 0/1 and zeros must become 1, so B is the all-ones matrix,
    # B^2 mod 2 has every entry equal to N mod 2.
    if p == 2:
        v = N & 1
        line = ' '.join(str(v) for _ in range(N))
        sys.stdout.write((line + '\n') * N)
        return

    # ---- count zeros, build M (zeros kept as 0) -------------------------
    K = 0
    M = [[0] * N for _ in range(N)]
    for i in range(N):
        Ai = A[i]; Mi = M[i]
        for j in range(N):
            v = Ai[j]
            if v == 0:
                K += 1
            else:
                Mi[j] = v % p

    # ---- M^p mod p ------------------------------------------------------
    try:
        import numpy as np
    except Exception:
        np = None

    if np is not None:
        Mp = matpow_np(M, p, p, N, np)
    else:
        Mp = matpow_py(M, p, p, N)

    # ---- correction matrix C -------------------------------------------
    C = [[0] * N for _ in range(N)]
    for i in range(N):
        Ai = A[i]
        for j in range(N):
            if Ai[j] == 0:
                if i == j:
                    # zero self-loop used p-1 times -> row i and column i of M
                    Mi = M[i]
                    Ci = C[i]
                    for t in range(N):
                        Ci[t] += Mi[t]
                        C[t][i] += M[t][i]
                elif p == 3:
                    # non self-loop zero (i,j) used twice, glued by fixed (j,i)
                    C[i][j] += M[j][i]

    sign = 1 if (K & 1) == 0 else p - 1
    out = []
    for i in range(N):
        Mpi = Mp[i]; Ci = C[i]
        out.append(' '.join(str(((Mpi[j] + Ci[j]) % p) * sign % p)
                            for j in range(N)))
    sys.stdout.write('\n'.join(out) + '\n')


def matpow_py(M, e, p, N):
    def mul(A, B):
        C = [[0] * N for _ in range(N)]
        for i in range(N):
            Ai = A[i]; Ci = C[i]
            for k in range(N):
                a = Ai[k]
                if a:
                    Bk = B[k]
                    for j in range(N):
                        Ci[j] += a * Bk[j]
            for j in range(N):
                Ci[j] %= p
        return C

    res = [[1 if i == j else 0 for j in range(N)] for i in range(N)]
    base = [row[:] for row in M]
    while e:
        if e & 1:
            res = mul(res, base)
        e >>= 1
        if e:
            base = mul(base, base)
    return res


def matpow_np(M, e, p, N, np):
    c1 = 32768            # 2^15
    c2 = (1 << 30) % p

    def mul(A, B):
        # split each entry (< 2^30) into two 15-bit halves so the four
        # int64 products never overflow (max ~ N * 2^30 < 2^63).
        A0 = A & 32767
        A1 = A >> 15
        B0 = B & 32767
        B1 = B >> 15
        P00 = A0.dot(B0)
        P01 = A0.dot(B1)
        P10 = A1.dot(B0)
        P11 = A1.dot(B1)
        mid = (P01 + P10) % p
        res = P00 % p
        res = (res + (mid * c1) % p) % p
        res = (res + ((P11 % p) * c2) % p) % p
        return res

    base = np.array(M, dtype=np.int64)
    res = np.eye(N, dtype=np.int64)
    while e:
        if e & 1:
            res = mul(res, base)
        e >>= 1
        if e:
            base = mul(base, base)
    return res.tolist()


