import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0]); m = int(data[1])
    L = [0] * m
    R = [0] * m
    ptr = 2
    for i in range(m):
        L[i] = int(data[ptr]); R[i] = int(data[ptr + 1]); ptr += 2

    op = [0] * m

    # ---- cost 1: some interval equals [1, N], used as op1 ----
    for i in range(m):
        if L[i] == 1 and R[i] == n:
            op[i] = 1
            sys.stdout.write("1\n" + " ".join(map(str, op)) + "\n")
            return

    found = False

    # ---- cost 2, case A (tried FIRST): op1 interval pi contains op2 interval q ----
    # contains[i] iff exists j != i with L_j >= L_i and R_j <= R_i
    order = sorted(range(m), key=lambda i: L[i], reverse=True)
    contains = bytearray(m)
    minR = n + 1
    cnt = 0
    j = 0
    while j < m:
        k = j
        lv = L[order[j]]
        while k < m and L[order[k]] == lv:
            k += 1
        # merge the whole equal-L group before evaluating its members
        for t in range(j, k):
            ri = R[order[t]]
            if ri < minR:
                minR = ri; cnt = 1
            elif ri == minR:
                cnt += 1
        for t in range(j, k):
            i = order[t]
            if R[i] > minR or (R[i] == minR and cnt >= 2):
                contains[i] = 1
        j = k

    pi = -1
    for i in range(m):
        if contains[i]:
            pi = i
            break
    if pi != -1:
        Lp = L[pi]; Rp = R[pi]
        for i in range(m):
            if i != pi and L[i] >= Lp and R[i] <= Rp:
                op[pi] = 1; op[i] = 2
                found = True
                break

    # ---- cost 2, case B: two op1 whose union is [1, N] ----
    if not found:
        a = -1; bestR1 = -1
        for i in range(m):
            if L[i] == 1 and R[i] > bestR1:
                bestR1 = R[i]; a = i
        b = -1; bestLN = n + 1
        for i in range(m):
            if R[i] == n and L[i] < bestLN:
                bestLN = L[i]; b = i
        if a != -1 and b != -1 and a != b and bestR1 + 1 >= bestLN:
            op[a] = 1; op[b] = 1
            found = True

    # ---- cost 2, case C: two disjoint op2 intervals ----
    if not found:
        p2 = 0
        for i in range(1, m):
            if R[i] < R[p2]:
                p2 = i
        q2 = 0
        for i in range(1, m):
            if L[i] > L[q2]:
                q2 = i
        if p2 != q2 and R[p2] < L[q2]:
            op[p2] = 2; op[q2] = 2
            found = True

    if found:
        sys.stdout.write("2\n" + " ".join(map(str, op)) + "\n")
        return

    # ---- cost 3 (only reachable when M >= 3) ----
    if m >= 3:
        ista = 0
        for i in range(1, m):
            if L[i] > L[ista]:
                ista = i
        jsta = 0
        for i in range(1, m):
            if R[i] < R[jsta]:
                jsta = i
        kk = -1
        for t in range(m):
            if t != ista and t != jsta:
                kk = t
                break
        op[ista] = 2; op[jsta] = 2; op[kk] = 1
        sys.stdout.write("3\n" + " ".join(map(str, op)) + "\n")
        return

    sys.stdout.write("-1\n")

main()

import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1
    K = int(data[idx]); idx += 1
    edges = []
    for _ in range(M):
        u = int(data[idx]) - 1; idx += 1
        v = int(data[idx]) - 1; idx += 1
        edges.append((u, v))

    INF = M + 1                       # > K and > any finite cut (|S| <= M)
    sys.setrecursionlimit(1 << 20)

    class Dinic:
        __slots__ = ('n', 'g', 'level', 'it')
        def __init__(self, n):
            self.n = n
            self.g = [[] for _ in range(n)]
            self.level = [0] * n
            self.it = [0] * n

        def add_edge(self, u, v, c):
            self.g[u].append([v, c, len(self.g[v])])
            self.g[v].append([u, 0, len(self.g[u]) - 1])

        def bfs(self, s, t):
            level = [-1] * self.n
            level[s] = 0
            q = deque([s])
            g = self.g
            while q:
                u = q.popleft()
                lu = level[u]
                for e in g[u]:
                    if e[1] > 0 and level[e[0]] < 0:
                        level[e[0]] = lu + 1
                        q.append(e[0])
            self.level = level
            return level[t] >= 0

        def dfs(self, u, t, f):
            if u == t:
                return f
            g = self.g; level = self.level; it = self.it
            while it[u] < len(g[u]):
                e = g[u][it[u]]
                if e[1] > 0 and level[e[0]] == level[u] + 1:
                    d = self.dfs(e[0], t, f if f < e[1] else e[1])
                    if d > 0:
                        e[1] -= d
                        g[e[0]][e[2]][1] += d
                        return d
                it[u] += 1
            return 0

        def maxflow_limited(self, s, t, limit):
            flow = 0
            while flow <= limit and self.bfs(s, t):
                self.it = [0] * self.n
                while flow <= limit:
                    f = self.dfs(s, t, 1 << 60)
                    if f == 0:
                        break
                    flow += f
            return flow

    def feasible(d):
        # Can we mark <= K edges so every 1->N path has >= d marked edges?
        if d == 0:
            return True
        total = N * d
        S = total; T = total + 1
        din = Dinic(total + 2)

        def node(v, k):              # k in 1..d, y_{v,k} = [L(v) >= k]
            return v * d + (k - 1)

        for k in range(1, d + 1):
            din.add_edge(S, node(N - 1, k), INF)   # force L(N) = d
            din.add_edge(node(0, k), T, INF)       # force L(1) = 0
        for v in range(N):
            for k in range(1, d):
                din.add_edge(node(v, k + 1), node(v, k), INF)   # monotone

        for (u, v) in edges:
            for k in range(1, d + 1):
                din.add_edge(node(v, k), node(u, k), 1)         # cost of a step up
            for k in range(2, d + 1):
                din.add_edge(node(v, k), node(u, k - 1), INF)   # L(v) <= L(u)+1

        return din.maxflow_limited(S, T, K) <= K

    ans = 0
    for d in range(1, N):            # shortest path is simple -> <= N-1 edges
        if feasible(d):
            ans = d
        else:
            break                    # feasibility is downward-closed in d
    print(ans)

main()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    ptr = 0
    N = int(data[ptr]); M = int(data[ptr + 1]); Q = int(data[ptr + 2]); ptr += 3
    a = [0] * (M + 1); b = [0] * (M + 1); sg = [0] * (M + 1)
    for i in range(1, M + 1):
        S = int(data[ptr]); Tv = int(data[ptr + 1]); ptr += 2
        if S < Tv:
            a[i] = S; b[i] = Tv; sg[i] = 1
        else:
            a[i] = Tv; b[i] = S; sg[i] = -1

    prev = [0] * (M + 1)
    # same left endpoint
    last = [0] * (N + 1)
    for j in range(1, M + 1):
        x = a[j]
        if last[x] > prev[j]:
            prev[j] = last[x]
        last[x] = j
    # same right endpoint
    last = [0] * (N + 1)
    for j in range(1, M + 1):
        y = b[j]
        if last[y] > prev[j]:
            prev[j] = last[y]
        last[y] = j

    size = 1
    while size < N + 1:
        size <<= 1
    TT = [0] * (2 * size)
    VV = [0] * (2 * size)
    ver_box = [0]

    def sweepA(L, R, ca, cb):
        ver = ver_box[0] + 1; ver_box[0] = ver
        tt = TT; vv = VV; pv = prev; sz = size
        p_ = 0; nL = len(L)
        for j in R:
            aj = ca[j]
            while p_ < nL:
                i = L[p_]
                if ca[i] >= aj:
                    break
                q = cb[i] + sz
                if vv[q] != ver:
                    vv[q] = ver; tt[q] = 0
                if tt[q] < i:
                    tt[q] = i
                    q >>= 1
                    while q:
                        lc = q << 1; rc = lc | 1
                        vl = tt[lc] if vv[lc] == ver else 0
                        vr = tt[rc] if vv[rc] == ver else 0
                        nv = vl if vl > vr else vr
                        if vv[q] != ver:
                            vv[q] = ver; tt[q] = 0
                        if tt[q] >= nv:
                            break
                        tt[q] = nv
                        q >>= 1
                p_ += 1
            l = aj + 1 + sz
            r = cb[j] - 1 + sz + 1
            res = 0
            while l < r:
                if l & 1:
                    if vv[l] == ver and tt[l] > res:
                        res = tt[l]
                    l += 1
                if r & 1:
                    r -= 1
                    if vv[r] == ver and tt[r] > res:
                        res = tt[r]
                l >>= 1; r >>= 1
            if res > pv[j]:
                pv[j] = res

    def merge_run(X, Y, ca):
        if not X: return Y
        if not Y: return X
        res = []; ap = res.append
        i = 0; j = 0; nx = len(X); ny = len(Y)
        while i < nx and j < ny:
            if ca[X[i]] <= ca[Y[j]]:
                ap(X[i]); i += 1
            else:
                ap(Y[j]); j += 1
        if i < nx: res.extend(X[i:])
        if j < ny: res.extend(Y[j:])
        return res

    def run(ca, cb):
        nodes = []
        for i in range(1, M + 1):
            if sg[i] == 1:
                nodes.append(([i], []))
            else:
                nodes.append(([], [i]))
        while len(nodes) > 1:
            nn = []
            i = 0; n = len(nodes)
            while i + 1 < n:
                LP, LM = nodes[i]
                RP, RM = nodes[i + 1]
                if LP and RP:
                    sweepA(LP, RP, ca, cb)
                if LM and RM:
                    sweepA(LM, RM, ca, cb)
                nn.append((merge_run(LP, RP, ca), merge_run(LM, RM, ca)))
                i += 2
            if i < n:
                nn.append(nodes[i])
            nodes = nn

    # pattern A: a_i < a_j < b_i < b_j
    run(a, b)
    # pattern B via mirror: a'=N+1-b, b'=N+1-a
    ma = [0] * (M + 1); mb = [0] * (M + 1)
    for i in range(1, M + 1):
        ma[i] = N + 1 - b[i]
        mb[i] = N + 1 - a[i]
    run(ma, mb)

    pref = [0] * (M + 1)
    cur = 0
    for j in range(1, M + 1):
        pj = prev[j]
        if pj > cur:
            cur = pj
        pref[j] = cur

    out = []
    for _ in range(Q):
        L = int(data[ptr]); R = int(data[ptr + 1]); ptr += 2
        out.append("No" if pref[R] >= L else "Yes")
    sys.stdout.write("\n".join(out))

