import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0]); X = int(data[1]); Y = int(data[2])
    S = data[3].decode(); T = data[4].decode()

    L = X + Y
    # No window of length X+Y exists -> no operation possible.
    if L > N:
        print("Yes" if S == T else "No")
        return

    def build_pref(s):
        p = [0] * (N + 1)
        for i, c in enumerate(s):
            p[i + 1] = p[i] + (1 if c == '1' else 0)
        return p

    def has_move(s, pref):
        # any i with 0^X 1^Y or 1^Y 0^X starting at i
        for i in range(0, N - L + 1):
            if pref[i + X] - pref[i] == 0 and pref[i + L] - pref[i + X] == Y:
                return True
            if pref[i + Y] - pref[i] == Y and pref[i + L] - pref[i + Y] == 0:
                return True
        return False

    pS = build_pref(S)
    pT = build_pref(T)
    # A string with no valid operation is isolated (component = {itself}).
    if (not has_move(S, pS)) or (not has_move(T, pT)):
        print("Yes" if S == T else "No")
        return

    def key(s):
        zeros = tuple(i % Y for i, ch in enumerate(s) if ch == '0')
        ones = tuple(i % X for i, ch in enumerate(s) if ch == '1')
        return (zeros, ones)

    print("Yes" if key(S) == key(T) else "No")

if __name__ == "__main__":
    solve()

import sys
import heapq
from collections import deque


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    pos = 0
    N = int(data[pos]); pos += 1
    M = int(data[pos]); pos += 1
    S = int(data[pos]) - 1; pos += 1
    T = int(data[pos]) - 1; pos += 1
    adj = [[] for _ in range(N)]
    for i in range(M):
        u = int(data[pos]) - 1; pos += 1
        v = int(data[pos]) - 1; pos += 1
        adj[u].append((v, i))
        adj[v].append((u, i))

    BIG = 1 << 60

    def bfs(src):
        dist = [-1] * N
        dist[src] = 0
        dq = deque([src])
        while dq:
            u = dq.popleft()
            du = dist[u] + 1
            for v, _ in adj[u]:
                if dist[v] == -1:
                    dist[v] = du
                    dq.append(v)
        return dist

    dS = bfs(S)
    dT = bfs(T)
    L = dS[T]

    # ---- buffer gadget: v on some shortest S-T path with deg>=3 ----
    ans = BIG
    for v in range(N):
        if len(adj[v]) >= 3 and dS[v] + dT[v] == L:
            pen = 4 if (v == S or v == T) else 2
            cand = 2 * L + pen
            if cand < ans:
                ans = cand

    # ---- biconnected components (blocks), iterative Tarjan ----
    disc = [-1] * N
    low = [0] * N
    pe = [-1] * N
    it = [0] * N
    estack = []
    blocks = []
    is_art = [False] * N
    timer = 0
    for s in range(N):
        if disc[s] != -1:
            continue
        disc[s] = low[s] = timer; timer += 1
        stack = [s]
        child = 0
        while stack:
            u = stack[-1]
            if it[u] < len(adj[u]):
                v, eid = adj[u][it[u]]
                it[u] += 1
                if eid == pe[u]:
                    continue
                if disc[v] == -1:
                    estack.append((u, v))
                    pe[v] = eid
                    disc[v] = low[v] = timer; timer += 1
                    stack.append(v)
                    if u == s:
                        child += 1
                elif disc[v] < disc[u]:
                    estack.append((u, v))
                    if disc[v] < low[u]:
                        low[u] = disc[v]
            else:
                stack.pop()
                if stack:
                    p = stack[-1]
                    if low[u] < low[p]:
                        low[p] = low[u]
                    if low[u] >= disc[p]:
                        comp = []
                        while True:
                            e = estack.pop()
                            comp.append(e)
                            if e == (p, u):
                                break
                        blocks.append(comp)
                        is_art[p] = True
        is_art[s] = (child >= 2)

    B = len(blocks)
    block_vertices = []
    block_of = [-1] * N
    for bi, comp in enumerate(blocks):
        vs = set()
        for u, v in comp:
            vs.add(u); vs.add(v)
        block_vertices.append(vs)
        for v in vs:
            if not is_art[v]:
                block_of[v] = bi

    total = B + N
    bct = [[] for _ in range(total)]
    for bi in range(B):
        for v in block_vertices[bi]:
            if is_art[v]:
                a = B + v
                bct[bi].append(a)
                bct[a].append(bi)

    start = B + S if is_art[S] else block_of[S]
    target = B + T if is_art[T] else block_of[T]

    par = [-1] * total
    seen = [False] * total
    dq = deque([start])
    seen[start] = True
    while dq:
        u = dq.popleft()
        if u == target:
            break
        for w in bct[u]:
            if not seen[w]:
                seen[w] = True
                par[w] = u
                dq.append(w)
    path = []
    cur = target
    while cur != -1:
        path.append(cur)
        cur = par[cur]
    path.reverse()

    # ---- min-cost 2-flow = shortest cycle through x,y inside a block ----
    def min_cycle(comp, x, y):
        vid = {}
        for u, v in comp:
            if u not in vid: vid[u] = len(vid)
            if v not in vid: vid[v] = len(vid)
        if x not in vid or y not in vid:
            return BIG
        n = len(vid)
        ix = vid[x]; iy = vid[y]
        N2 = 2 * n
        graph = [[] for _ in range(N2)]

        def add(u, v, cap, cost):
            graph[u].append([v, cap, cost, len(graph[v])])
            graph[v].append([u, 0, -cost, len(graph[u]) - 1])

        for i in range(n):
            c = 2 if (i == ix or i == iy) else 1
            add(2 * i, 2 * i + 1, c, 0)
        for u, v in comp:
            iu = vid[u]; iv = vid[v]
            add(2 * iu + 1, 2 * iv, 1, 1)
            add(2 * iv + 1, 2 * iu, 1, 1)
        s = 2 * ix; t = 2 * iy
        h = [0] * N2
        prevv = [0] * N2
        preve = [0] * N2
        flow = 0; cost = 0
        while flow < 2:
            dist = [BIG] * N2
            dist[s] = 0
            pq = [(0, s)]
            while pq:
                d, u = heapq.heappop(pq)
                if d > dist[u]:
                    continue
                hu = h[u]
                for i, e in enumerate(graph[u]):
                    if e[1] > 0:
                        v = e[0]
                        nd = d + e[2] + hu - h[v]
                        if nd < dist[v]:
                            dist[v] = nd
                            prevv[v] = u; preve[v] = i
                            heapq.heappush(pq, (nd, v))
            if dist[t] >= BIG:
                return BIG
            for v in range(N2):
                if dist[v] < BIG:
                    h[v] += dist[v]
            d = 2 - flow
            v = t
            while v != s:
                e = graph[prevv[v]][preve[v]]
                if e[1] < d:
                    d = e[1]
                v = prevv[v]
            v = t
            while v != s:
                e = graph[prevv[v]][preve[v]]
                e[1] -= d
                graph[v][e[3]][1] += d
                v = prevv[v]
            flow += d
            cost += d * h[t]
        return cost

    plen = len(path)
    for i, node in enumerate(path):
        if node < B:
            if len(block_vertices[node]) < 3:
                continue
            x = S if i == 0 else path[i - 1] - B
            y = T if i == plen - 1 else path[i + 1] - B
            # quick lower bound: min_cycle >= 3
            if 2 * (dS[x] + dT[y]) + 3 >= ans:
                continue
            c = min_cycle(blocks[node], x, y)
            if c < BIG:
                cand = 2 * (dS[x] + dT[y]) + c
                if cand < ans:
                    ans = cand

    print(ans if ans < BIG else -1)


if __name__ == "__main__":
    main()

import sys

MOD = 998244353
_NB = 10          # 10-byte (80-bit) slots give exact big-int convolution
_NAIVE = 8000     # schoolbook threshold (product of operand lengths)
_DIRECT = 1500    # O(m^2) DP up to this many live indices
_THRESH = 4000    # naive CDQ cross when left_cnt*right_cnt <= this


def _pack(a):
    nb = _NB
    ba = bytearray(len(a) * nb)
    off = 0
    for v in a:
        ba[off:off + nb] = v.to_bytes(nb, 'little')
        off += nb
    return int.from_bytes(ba, 'little')


def convolution(A, B):
    la = len(A)
    lb = len(B)
    if la == 0 or lb == 0:
        return []
    if la == 1:
        a0 = A[0]
        return [a0 * b % MOD for b in B]
    if lb == 1:
        b0 = B[0]
        return [b0 * a % MOD for a in A]
    if la * lb <= _NAIVE:
        res = [0] * (la + lb - 1)
        for i in range(la):
            a = A[i]
            if a:
                for j in range(lb):
                    res[i + j] = (res[i + j] + a * B[j]) % MOD
        return res
    # Exact integer convolution. coeff < MOD ~ 2^30, so any output coeff
    # <= min(la,lb)*(MOD-1)^2 < 2^78 < 2^80: no slot carry.
    P = _pack(A) * _pack(B)
    count = la + lb - 1
    nb = _NB
    by = P.to_bytes(count * nb + nb, 'little')
    res = [0] * count
    for i in range(count):
        res[i] = int.from_bytes(by[i * nb:i * nb + nb], 'little') % MOD
    return res


def poly_inv(A, n):
    B = [pow(A[0], MOD - 2, MOD)]
    while len(B) < n:
        L = min(2 * len(B), n)
        AB = convolution(A[:L], B)[:L]
        for i in range(L):
            AB[i] = (-AB[i]) % MOD
        AB[0] = (AB[0] + 2) % MOD
        B = convolution(B, AB)[:L]
    return B


def solve(N, S):
    # Strong connectivity requires S[0]='B' and S[-1]='W'.
    if S[0] != 'B' or S[-1] != 'W':
        return 0

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (N + 1)
    inv_fact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    # t[i] = number of W before the (i+1)-th B, for i = 1..N-1.
    t = [0] * (N + 1)
    wc = 0
    bc = 0
    for c in S:
        if c == 'W':
            wc += 1
        else:
            bc += 1
            if bc >= 2:
                t[bc - 1] = wc

    # Live indices: starts of maximal constant-t runs with value >= start.
    idx = [0]
    Tv = [0]
    i = 1
    while i < N:
        tv = t[i]
        st = i
        while i < N and t[i] == tv:
            i += 1
        if tv >= st:
            idx.append(st)
            Tv.append(tv)
    m = len(idx) - 1

    if m == 0:
        return fact[N] % MOD

    # Fast path: idx[k] = s*k and Tv[k]-idx[k] = d constant.
    # Then A(x)*K(x)=fact[d], K(x)=sum fact[d+s*k] x^k, A_k = W_k.
    s = idx[1]
    d = Tv[1] - idx[1]
    ok = True
    for k in range(1, m + 1):
        if idx[k] != s * k or Tv[k] - idx[k] != d:
            ok = False
            break
    if ok:
        K = [fact[d + s * k] for k in range(m + 1)]
        invK = poly_inv(K, m + 1)
        f0 = fact[d]
        ans = 0
        for k in range(m + 1):
            ans = (ans + f0 * invK[k] % MOD * fact[N - s * k]) % MOD
        return ans

    # Small m: direct O(m^2) DP.
    if m <= _DIRECT:
        W = [0] * (m + 1)
        W[0] = 1
        for k in range(1, m + 1):
            Tk = Tv[k]
            sm = 0
            for l in range(k):
                wl = W[l]
                if wl:
                    sm = (sm + wl * fact[Tk - idx[l]]) % MOD
            W[k] = (-inv_fact[Tk - idx[k]] * sm) % MOD
        ans = W[0] * fact[N] % MOD
        for k in range(1, m + 1):
            ans = (ans + W[k] * fact[N - idx[k]]) % MOD
        return ans

    # General case: CDQ divide & conquer.
    W = [0] * (m + 1)
    Sacc = [0] * (m + 1)

    def cdq(l, r):
        if l == r:
            if l == 0:
                W[0] = 1
            else:
                W[l] = (-inv_fact[Tv[l] - idx[l]]) * Sacc[l] % MOD
            return
        mid = (l + r) >> 1
        cdq(l, mid)
        if mid + 1 <= r:
            offset = idx[l]
            if (mid - l + 1) * (r - mid) <= _THRESH:
                for k in range(mid + 1, r + 1):
                    Tk = Tv[k]
                    sm = 0
                    for j in range(l, mid + 1):
                        wj = W[j]
                        if wj:
                            sm = (sm + wj * fact[Tk - idx[j]]) % MOD
                    Sacc[k] = (Sacc[k] + sm) % MOD
            else:
                base = Tv[mid + 1] - idx[mid]
                lenA = idx[mid] - offset + 1
                lenB = Tv[r] - offset - base + 1
                A = [0] * lenA
                for j in range(l, mid + 1):
                    wj = W[j]
                    if wj:
                        A[idx[j] - offset] = wj
                B = fact[base:base + lenB]
                C = convolution(A, B)
                for k in range(mid + 1, r + 1):
                    pos = Tv[k] - offset - base
                    Sacc[k] = (Sacc[k] + C[pos]) % MOD
        cdq(mid + 1, r)

    cdq(0, m)
    ans = W[0] * fact[N] % MOD
    for k in range(1, m + 1):
        ans = (ans + W[k] * fact[N - idx[k]]) % MOD
    return ans


def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    S = data[1].decode()
    sys.stdout.write(str(solve(N, S) % MOD) + "\n")


if __name__ == '__main__':
    main()
